  'plans.eyebrow':'Kuukausiohjelma','plans.title':'Kehon uudelleenrakennus',
  'plans.lede':'Rasvanpudotus, lihasmassan kasvu ja liikkuvuus. Paleo-proteiiniravinto optimoidulla rasvan käytöllä. Ei sitoutumista, kuukausimaksu.',
  'plans.p1.price':'Kysy hintaa','plans.p2.price':'Kysy hintaa','plans.p3.price':'Kysy hintaa','plans.p4.price':'Kysy hintaa',
  'plans.choose':'Valitse','plans.popular':'Suosituin',
  'plans.p1.t':'Karl','plans.p1.s':'Itsenäinen soturi. Harjoittelu- ja ravintosuunnitelmasi, valmiina toteutettavaksi.',
